<script setup>import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth.js';const router=useRouter();const{user,isAdmin,logout}=useAuth();function signOut(){logout();router.push('/');}</script>
<template><header class="topbar"><button class="logo" @click="router.push('/')"><span>F</span><div>FastTravel</div></button><nav><RouterLink to="/">Trang chủ</RouterLink><RouterLink to="/account">Vé xe</RouterLink><RouterLink to="/policy">Khuyến mãi</RouterLink><RouterLink to="/contact">Hỗ trợ</RouterLink><RouterLink v-if="isAdmin" class="admin-link" to="/admin">Quản trị</RouterLink></nav><div class="account"><template v-if="user"><span class="avatar">{{user.fullName?.[0]}}</span><div><b>{{user.fullName}}</b><small>{{user.role}}</small></div><button @click="signOut">Thoát</button></template><template v-else><RouterLink class="login-link" to="/auth">Đăng nhập</RouterLink><RouterLink class="btn primary" to="/auth?mode=register">Đăng ký</RouterLink></template></div></header></template>
